package com.mkii.coursemanagementsystem.dao;

import java.util.List;
import java.util.Map;

public interface BaseDao<T> {
    T save(T entity);
    void delete(Long id);
    T update(T entity);
    T findById(Long id);
    List<T> findAll();
    long count();
    List<T> findByCriteria(Map<String, Object> criteria);
}
```

